import{_ as e,o as t,a as c,b as h}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/npu_3510_hw_arch_cache.k_V3HJN_.png",i="/ascendc.github.io/pr/5487/assets/atlas_a2_a3_cache_architecture_diagram.B2XYb49X.png",D=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"缓存控制","link":"/api/SIMD-API/basic_api/cache_control/cache_control"},{"text":"系统缓存概述","link":"/api/SIMD-API/basic_api/cache_control/system_cache_overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cache_control/system_cache_overview.md","filePath":"api/SIMD-API/basic_api/cache_control/system_cache_overview.md","outlineHeaders":[{"level":2,"title":"Cache类型","slug":"Cache类型","link":"#Cache类型"},{"level":2,"title":"Cache操作及使用场景","slug":"Cache操作及使用场景","link":"#Cache操作及使用场景"},{"level":2,"title":"Cache写策略与Cache一致性问题","slug":"Cache写策略与Cache一致性问题","link":"#Cache写策略与Cache一致性问题"},{"level":2,"title":"缓存控制接口汇总","slug":"缓存控制接口汇总","link":"#缓存控制接口汇总"}],"lastUpdated":1788329934000}'),d={name:"api/SIMD-API/basic_api/cache_control/system_cache_overview.md"};function l(C,a,s,n,o,_){return t(),c("div",null,[...a[0]||(a[0]=[h('<div><article class="markdown-body"><h1>系统缓存概述<span id="ZH-CN_TOPIC_0000002594407823"></span></h1><h2 id="Cache类型">Cache类型<span id="zh-cn_topic_0000002583420201_section112105011415"></span><a class="header-anchor" href="#Cache类型">​</a></h2><p>Cache（缓存）的主要作用是在搬运单元或Scalar单元与外部存储之间提供一层高速缓冲，以降低数据访问延迟并提高带宽利用率。通常情况下，被频繁访问的数据会写入Cache，搬运单元或Scalar单元在执行过程中优先从Cache中读取数据；当Cache未命中时，再从外部存储加载数据并更新到Cache中。</p><p><a href="#table1">表1</a>展示了不同类型的Cache的功能，不同产品中支持的Cache类型不同，具体情况如下：</p><div data-filter="950"><p>以<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>为例，图1展示了AI Core中支持的五类Cache（L2 Cache、DCache、ICache、SIMT DCache、NDDMA Cache）在硬件架构中的位置关系。</p><p><strong>图1</strong> 五类Cache在AI Core中的位置关系示意图<br><img src="'+r+'" alt title="atlas_950_cache_architecture_diagram"></p></div><div data-filter="A3,910b"><p>以<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>为例，图2展示了AI Core中支持的三类Cache（L2 Cache、DCache和ICache）在硬件架构中的位置关系。</p><p><strong>图2</strong> 三类Cache在AI Core中的位置关系示意图<span id="zh-cn_topic_0000002583420201_fig496311278412"></span><br><img src="'+i+'" alt title="atlas_a2_a3_cache_architecture_diagram"></p></div><p><strong>表1</strong> Cache类型及功能说明 <span id="table1"></span></p><table><thead><tr><th>Cache类型</th><th>说明</th></tr></thead><tbody><tr><td>L2 Cache</td><td>L2 Cache作为二级缓存，专门用于存储频繁访问的数据和指令，以便减少对GM的读写。<br>•通过MTE2单元读取GM时，优先从L2 Cache中读取数据；当L2 Cache未命中时，再从GM加载数据并更新到L2 Cache中。<br>•通过Scalar单元读取GM时，优先从DCache中读取数据；当DCache未命中时，再从L2 Cache中读取数据。当L2 Cache也未命中时，再从GM加载数据并更新到L2 Cache和DCache中。<br>•通过Scalar单元读取GM指令时，优先从ICache中读取指令；当ICache未命中时，再从L2 Cache中读取指令。当L2 Cache也未命中时，再从GM加载指令并更新到L2 Cache和ICache中。</td></tr><tr><td>DCache</td><td>DCache（Data Cache）用于缓存Scalar单元近期可能被重复访问的数据段。<br>通过Scalar单元读取GM时，优先从DCache中读取数据；当DCache未命中时，再从L2 Cache中读取数据。当L2 Cache也未命中时，再从GM加载数据并更新到L2 Cache和DCache中。</td></tr><tr><td>ICache</td><td>ICache（Instruction Cache）用于缓存Scalar单元最近使用或频繁使用的指令。<br>通过Scalar单元读取GM指令时，优先从ICache中读取指令；当ICache未命中时，再从L2 Cache中读取指令。当L2 Cache也未命中时，再从GM加载指令并更新到L2 Cache和ICache中。</td></tr><tr><td>SIMT DCache</td><td>SIMT访问GM需要经过SIMT DCache中转。数据流经由GM到SIMT DCache，再从SIMT DCache到SIMT寄存器，SIMT DCache充当中间缓冲层，减少对GM的直接访问次数。</td></tr><tr><td>NDDMA Cache</td><td>NDDMA Cache用于缓存最近或即将被<a href="../../basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_NDDMA.html">DataCopy（GMToUB多维数据搬运NDDMA）</a>接口搬运的数据。</td></tr></tbody></table><h2 id="Cache操作及使用场景">Cache操作及使用场景<span id="zh-cn_topic_0000002583420201_section054554323117"></span><a class="header-anchor" href="#Cache操作及使用场景">​</a></h2><p>表2介绍了缓存的四种基础操作及其核心功能。</p><p><strong>表2</strong> Cache操作及功能说明</p><table><thead><tr><th>操作名称</th><th>功能说明</th></tr></thead><tbody><tr><td>Prefetch</td><td>硬件根据访问模式自动将预期访问的数据提前加载到缓存，提升后续访问速度。</td></tr><tr><td>Preload</td><td>软件通过显式指令将指定数据主动加载到缓存，为即将到来的读写操作做准备。</td></tr><tr><td>Invalid</td><td>•将指定地址范围的Cache Line（缓存的最小操作单元）标记为“无效”，使其从缓存中移除。<br>•保证下一次访问这些内存地址时，会从GM重新加载数据，而不是使用可能过期的缓存数据。<br>•注意：Invalid操作不检查缓存行是否为“脏”（dirty，表示该数据已被修改但尚未写回到GM），若存在脏数据将被直接丢弃。</td></tr><tr><td>Clean</td><td>将缓存中被修改过的数据（脏数据）写回到GM中，避免数据丢失。Clean操作不将缓存行标记为“无效”，缓存行仍保持有效状态。</td></tr></tbody></table><h2 id="Cache写策略与Cache一致性问题">Cache写策略与Cache一致性问题<span id="zh-cn_topic_0000002583420201_section053731716357"></span><a class="header-anchor" href="#Cache写策略与Cache一致性问题">​</a></h2><p>当向GM写入数据，并且启用Cache时，存在以下两种Cache写策略：延迟写回（Write-Back）和直写（Write-Through）。</p><p>当向GM写数据时采取延迟写回策略，工作原理如下：</p><ul><li><p>开发者预期向GM写入数据（即期望数据直接写入GM），硬件实际行为是：</p><ul><li>当数据被修改时，只在缓存中更新数据。</li><li>缓存中的数据标记为“脏”。</li><li>当该Cache Line被替换时（或通过软件显式执行Clean操作时），数据才会被写回GM，Cache Line何时被替换由硬件决定。</li></ul></li><li><p>替换Cache Line数据时：</p><ul><li>当缓存空间不足需要替换数据时，检查被替换的数据是否为“脏”。</li><li>如果是“脏”数据，先将其写回到GM，然后再将该Cache Line替换出缓存。</li></ul></li></ul><p>当向GM写入数据时，若采用直写（Write-Through）策略，其工作原理如下：</p><ul><li><p>开发者预期向GM写入数据（即期望数据直接写入GM），硬件实际行为是：</p><ul><li>当数据被修改时，立即在缓存和GM中更新数据。</li><li>缓存行无需标记为“脏”。</li></ul></li><li><p>替换Cache Line数据时：</p><p>由于每次写数据都同步更新GM，因此缓存中的数据不存在“脏”状态，也无需在替换时额外写回GM。</p></li></ul><p>在延迟写回策略下，被修改的数据仅更新在本地缓存中，不会立即同步到GM。当其他核读取GM上同一地址时，获取的将是过时数据，从而导致不同核间缓存数据不一致。 Cache一致性是多核中确保数据正确性的核心机制。简单来说，当多个核各自拥有独立的Cache时，它们可能同时缓存相同的数据。如果某个核修改了缓存中的数据，其他核的缓存副本就会变得“过时”，如果不及时同步，就会导致多个核间的数据不一致，进而引发计算错误。</p><div data-filter="950,A3,910b"><p>下面介绍不同产品中每种类型Cache是否需要考虑多核间数据不一致：</p><div data-filter="950"><ul><li>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，该产品支持的五类Cache在多核间数据一致性方面的情况如下： <ul><li>L2 Cache：多核间共享的缓存，因此不需要考虑多核间数据不一致的问题。</li><li>DCache：多核独立缓存，因此需要考虑多核间数据一致性的问题。</li><li>ICache：只读，因此不需要考虑多核间数据不一致的问题。</li><li>NDDMA Cache：多核独立缓存，因此需要考虑多核间数据一致性的问题。</li><li>SIMT DCache：在SIMT中，写入数据时会立即写入GM，不存在一致性问题；从GM读取数据时，多核独立缓存，需要考虑多核间数据一致性的问题。</li></ul></li></ul></div><div data-filter="A3,910b"><ul><li>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，支持的三类Cache在多核间数据一致性方面的情况如下： <ul><li>L2 Cache：多核间共享的缓存，因此不需要考虑多核间数据不一致的问题。</li><li>DCache：多核独立缓存，因此需要考虑多核间数据一致性的问题。</li><li>ICache：只读，因此不需要考虑多核间数据不一致的问题。</li></ul></li></ul></div></div><h2 id="缓存控制接口汇总">缓存控制接口汇总<span id="zh-cn_topic_0000002583420201_section489931219616"></span><a class="header-anchor" href="#缓存控制接口汇总">​</a></h2><p>表3按照Cache类型（L2 Cache、DCache、ICache、NDDMA Cache）汇总了与缓存控制相关的接口及其功能说明。</p><p><strong>表3</strong> 缓存控制接口汇总</p><table><thead><tr><th>Cache类型</th><th>接口名称</th><th>功能简述</th></tr></thead><tbody><tr><td>L2 Cache</td><td><a href="../../basic_api/data_structures/GlobalTensor/SetL2CacheHint.html">SetL2CacheHint</a></td><td>读写GM的数据都默认被缓存在L2 Cache（默认启用L2 Cache），SetL2CacheHint能够设置GlobalTensor是否启用L2 Cache。</td></tr><tr><td>DCache</td><td><a href="DataCachePreload.html">DataCachePreload</a></td><td>DataCachePreload接口从源地址所在的特定GM地址预加载数据到DCache中，每次调用只能预加载一个Cache Line大小的数据。</td></tr><tr><td>DCache</td><td><a href="DataCacheCleanAndInvalid.html">DataCacheCleanAndInvalid</a></td><td>当Scalar单元访问GM时，使用该接口刷新Cache，保证Cache的一致性，使用场景如下：<br>•读取GM的数据，但该数据可能在外部被其余核修改，此时需要使用DataCacheCleanAndInvalid接口，直接访问GM，获取最新数据。<br>•用户通过Scalar单元写GM的数据，希望立刻写出，也需要使用DataCacheCleanAndInvalid接口。</td></tr><tr><td>DCache</td><td><a href="../scalar_compute/ReadGmByPassDCache_ISASI.html">ReadGmByPassDCache</a>/<a href="../scalar_compute/WriteGmByPassDCache_ISASI.html">WriteGmByPassDCache</a></td><td>不经过DCache向GM地址上<strong>读</strong>/<strong>写</strong>数据。使用场景：<br>•当多个核写入的数据落在同一条Cache Line内时，经过DCache的读写将以64B为粒度，可能引发多核数据随机覆盖问题。使用该接口不经过DCache直接按操作数大小<strong>读</strong>/<strong>写</strong>GM，可避免此问题。<br>•使用该接口不经过DCache直接向GM<strong>读</strong>/<strong>写</strong>数据，可避免由DCache缓存引发的多核间数据不一致问题。</td></tr><tr><td>ICache</td><td><a href="ICachePreLoad_ISASI.html">ICachePreLoad</a></td><td>开发者手动调用ICachePreLoad接口，能够从指令所在GM地址预加载指令到ICache中。</td></tr><tr><td>ICache</td><td><a href="GetICachePreloadStatus_ISASI.html">GetICachePreloadStatus</a></td><td>GetICachePreloadStatus为调试接口，在调用ICachePreLoad后调用，用于获取ICache的PreLoad的状态。当返回值为0时，说明ICache的PreLoad已完成；当返回值为1时，说明ICache的PreLoad未完成。</td></tr><tr><td>NDDMA Cache</td><td>NdDmaDci</td><td>在使用<a href="../../basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_NDDMA.html">DataCopy（GMToUB多维数据搬运NDDMA）</a>接口进行数据搬运前，需要使用NdDmaDci接口刷新NDDMA Cache缓存保证为最新状态。</td></tr></tbody></table></article></div>',1)])])}const I=e(d,[["render",l]]);export{D as __pageData,I as default};
